#include "launcher.h"
#include "backend/backend_picture.h"   // ibBackendPicture::GetBitmapFromBase64

// The launcher's pictures (see launcher.h). Each is a drawing the set already has for the same act — the
// application is STARTED (run without debugging), the designer opens the CONFIGURATION, a base is added,
// edited, deleted, the launcher is left — and the web client's globe, which is its own.

/* PNG */
static const wxString s_launcherEnterprise_png = wxT("");
static const wxString s_launcherDesigner_png   = wxT("");
static const wxString s_launcherWeb_png        = wxT("");
static const wxString s_launcherAdd_png        = wxT("");
static const wxString s_launcherEdit_png       = wxT("");
static const wxString s_launcherDelete_png     = wxT("");
static const wxString s_launcherExit_png       = wxT("");

wxBitmapBundle ibGetLauncherPicture(ibLauncherPicture which)
{
	const wxString* png = nullptr;
	switch (which) {
		case ibLauncherPicture::Enterprise: png = &s_launcherEnterprise_png; break;
		case ibLauncherPicture::Designer:   png = &s_launcherDesigner_png;   break;
		case ibLauncherPicture::Web:        png = &s_launcherWeb_png;        break;
		case ibLauncherPicture::Add:        png = &s_launcherAdd_png;        break;
		case ibLauncherPicture::Edit:       png = &s_launcherEdit_png;       break;
		case ibLauncherPicture::Delete:     png = &s_launcherDelete_png;     break;
		case ibLauncherPicture::Exit:       png = &s_launcherExit_png;       break;
	}
	if (png == nullptr)
		return wxBitmapBundle();

	// The master is 64 px; offered at 16 and at 32, so a display scaled to 200 % gets a sharp one as well.
	return wxBitmapBundle::FromBitmaps(
		ibBackendPicture::GetBitmapFromBase64(*png, wxSize(16, 16)),
		ibBackendPicture::GetBitmapFromBase64(*png, wxSize(32, 32)));
}
